{
  "action": "answer",
  "assessment": "The observations from 'json-text' and 'path-write' provide the necessary documentation to answer how to serialize an object keeping non-ASCII characters and write it to a UTF-8 file.",
  "query": "",
  "source_id": "",
  "answer": "To serialize an object keeping non-ASCII characters in the JSON string, call `json.dumps(obj, ensure_ascii=False)`. To write that resulting string to a UTF-8 file, use `Path.write_text(data, encoding=\"utf-8\")`.",
  "citations": [
    {
      "source_id": "json-text",
      "quote": "Setting ensure_ascii=False leaves non-ASCII characters in that string."
    },
    {
      "source_id": "path-write",
      "quote": "Path.write_text(data, encoding=None, errors=None, newline=None) writes text to a file and closes it. Set encoding=\"utf-8\" to select UTF-8."
    }
  ]
}
